from typing import Dict

class InventoryRepository:
    def __init__(self):
        self.stock: Dict[str, int] = {
            "item_a": 10,
            "item_b": 5,
        }

    def get_stock(self, product_id: str) -> int:
        return self.stock.get(product_id, 0)

    def deduct_stock(self, item_payload: Dict[str, int]) -> bool:
        pid = item_payload["product_id"]
        qty = item_payload["quantity"]
        if self.stock.get(pid, 0) >= qty:
            self.stock[pid] -= qty
            return True
        return False

