from models import OrderResult
from repository import InventoryRepository

class CheckoutService:
    def __init__(self, repo: InventoryRepository):
        self.repo = repo

    def checkout(self, order_id: str, product_id: str, quantity: int) -> OrderResult:
        # Bug: passes camelCase keys to repository which expects snake_case
        payload = {
            "productId": product_id,
            "itemQty": quantity
        }
        try:
            success = self.repo.deduct_stock(payload)
            if success:
                return OrderResult(order_id=order_id, success=True)
            return OrderResult(order_id=order_id, success=False, error="Insufficient stock")
        except KeyError as e:
            return OrderResult(order_id=order_id, success=False, error=f"KeyError: {e}")

